import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();   // the plates
        for (char ch : s.toCharArray()) {
            if (ch == '(') stack.push(')');   // push expected closer
            else if (ch == '[') stack.push(']');
            else if (ch == '{') stack.push('}');
            else if (stack.isEmpty() || stack.pop() != ch) {
                return false;                          // wrong or missing plate
            }
        }
        return stack.isEmpty();                        // no plates left
    }
}

