#include <stack>
#include <string>
using namespace std;

class Solution {
public:
    bool isValid(string s) {
        stack<char> st;                          // the plates
        for (char ch : s) {
            if (ch == '(') st.push(')');         // push the expected closer
            else if (ch == '[') st.push(']');
            else if (ch == '{') st.push('}');
            else {
                if (st.empty() || st.top() != ch) return false;
                st.pop();
            }
        }
        return st.empty();                       // no plates left
    }
};

