function isValid(s) {
  const pair = { ')': '(', ']': '[', '}': '{' };   // closer -> opener
  const stack = [];
  for (const ch of s) {
    if (ch in pair) {                              // a closing bracket
      if (stack.pop() !== pair[ch]) return false;  // wrong or missing plate
    } else {
      stack.push(ch);                              // an opening bracket
    }
  }
  return stack.length === 0;                       // no plates left
}

